import functools
from collections import Counter


def test_counter_subclass_str():
    class Cnt2(Counter):
        __repr__ = lambda s: "X"

    print(Cnt2("a"))


def test_sm_qualnames():
    class T:
        @staticmethod
        def s():
            pass

        @classmethod
        def c(cls):
            pass

    print(T.s.__qualname__, T.s.__name__)
    print(T.c.__qualname__, T.c.__name__)
    print(repr(T.c))


def deco(f):
