def test_arg_errors():
    class K:
        def m(self, a):
            pass

    try:
        K().m()
    except TypeError as e:
        print(e)

    def outer():
        def need(a):
            pass

        try:
            need()
        except TypeError as e:
            print(e)

    outer()


def test_gen_qualnames():
    def gen():
