import functools
from collections import Counter


def test_counter_subclass_str():
    class Cnt2(Counter):
        __repr__ = lambda s: "X"

    print(Cnt2("a"))


def test_sm_qualnames():
    class T:
        @staticmethod
        def s():
            pass

        @classmethod
        def c(cls):
            pass

    print(T.s.__qualname__, T.s.__name__)
    print(T.c.__qualname__, T.c.__name__)
    print(repr(T.c))


def deco(f):
    @functools.wraps(f)
    def w(*a, **k):
        return f(*a, **k)

    return w


@deco
def top():
    pass


print(top.__qualname__, top.__name__, top.__wrapped__.__name__)


def test_arg_errors():
    class K:
        def m(self, a):
            pass

    try:
        K().m()
    except TypeError as e:
        print(e)

    def outer():
        def need(a):
            pass

        try:
            need()
        except TypeError as e:
            print(e)

    outer()


def test_gen_qualnames():
    def gen():
        yield 1

    g = gen()
    print(g.__qualname__, g.__name__)
